theorem Std.ExtDTreeMap.minKey?_le_of_mem.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] {k km : α} (hc : k ∈ t)
  (hkm : t.minKey?.get ⋯ = km) : (cmp km k).isLE = true

theorem Std.ExtDTreeMap.foldr_eq_foldr_keys.{u, v, w} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} {δ : Type w} [Std.TransCmp cmp] {f : α → δ → δ} {init : δ} :
  Std.ExtDTreeMap.foldr (fun a x d => f a d) init t = List.foldr f init t.keys

theorem Std.ExtDTreeMap.minKey_le_minKey_erase.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] {k : α} {he : t.erase k ≠ ∅} :
  (cmp (t.minKey ⋯) ((t.erase k).minKey he)).isLE = true

theorem Std.ExtDTreeMap.maxKey.congr_simp.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  [Std.TransCmp cmp] (t t✝ : Std.ExtDTreeMap α β cmp) (e_t : t = t✝) (h : t ≠ ∅) :
