theorem Std.ExtDTreeMap.Const.get?_union_of_not_mem_left.{u, v} {α : Type u} {cmp : α → α → Ordering}
  {β : Type v} {t₁ t₂ : Std.ExtDTreeMap α (fun x => β) cmp} [Std.TransCmp cmp] {k : α}
  (not_mem : k ∉ t₁) : Std.ExtDTreeMap.Const.get? (t₁.union t₂) k = Std.ExtDTreeMap.Const.get? t₂ k

theorem Std.ExtDTreeMap.modify.congr_simp.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] (t t✝ : Std.ExtDTreeMap α β cmp) (e_t : t = t✝) (a : α)
