theorem Std.ExtDTreeMap.Const.get!_eq_getD_default.{u, v} {α : Type u} {cmp : α → α → Ordering} {β : Type v}
  {t : Std.ExtDTreeMap α (fun x => β) cmp} [Std.TransCmp cmp] [Inhabited β] {a : α} :
  Std.ExtDTreeMap.Const.get! t a = Std.ExtDTreeMap.Const.getD t a default

theorem Std.ExtDTreeMap.getKeyD_alter.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] {k k' fallback : α}
  {f : Option (β k) → Option (β k)} :
  (t.alter k f).getKeyD k' fallback =
    if cmp k k' = Ordering.eq then if (f (t.get? k)).isSome = true then k else fallback
    else t.getKeyD k' fallback

theorem Std.ExtDTreeMap.Const.get!_filterMap_of_getKey?_eq_some.{u, v, w} {α : Type u}
  {cmp : α → α → Ordering} {β : Type v} {γ : Type w} {t : Std.ExtDTreeMap α (fun x => β) cmp}
  [Std.TransCmp cmp] [Inhabited γ] {f : α → β → Option γ} {k k' : α} (h : t.getKey? k = some k') :
  Std.ExtDTreeMap.Const.get! (Std.ExtDTreeMap.filterMap f t) k =
    ((Std.ExtDTreeMap.Const.get? t k).bind (f k')).get!

theorem Std.ExtDTreeMap.Const.getKey!_insertMany_list_of_contains_eq_false.{u, v} {α : Type u}
