  (contains_eq_false : (List.map Prod.fst l).contains k = false) :
  (Std.ExtDTreeMap.Const.insertMany t l).getKey! k = t.getKey! k

theorem Std.ExtDTreeMap.get?_eq_some_get!.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] {a : α} [Inhabited (β a)] :
