theorem Std.ExtDTreeMap.Const.get!_congr.{u, v} {α : Type u} {cmp : α → α → Ordering} {β : Type v}
  {t : Std.ExtDTreeMap α (fun x => β) cmp} [Std.TransCmp cmp] [Inhabited β] {a b : α}
  (hab : cmp a b = Ordering.eq) : Std.ExtDTreeMap.Const.get! t a = Std.ExtDTreeMap.Const.get! t b

theorem Std.ExtDTreeMap.ne_empty_of_erase_ne_empty.{u, v} {α : Type u} {β : α → Type v}
  {cmp : α → α → Ordering} {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] {k : α}
  (h : t.erase k ≠ ∅) : t ≠ ∅

theorem Std.ExtDTreeMap.ext_get?_iff.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] {t₁ t₂ : Std.ExtDTreeMap α β cmp} :
  t₁ = t₂ ↔ ∀ (k : α), t₁.get? k = t₂.get? k

theorem Std.ExtDTreeMap.maxKey?_alter_eq_self.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] {k : α}
  {f : Option (β k) → Option (β k)} :
  (t.alter k f).maxKey? = some k ↔ (f (t.get? k)).isSome = true ∧ ∀ k' ∈ t, (cmp k' k).isLE = true

theorem Std.ExtDTreeMap.Const.unitOfList_eq_insertManyIfNewUnit_empty.{u} {α : Type u}
  {cmp : α → α → Ordering} [Std.TransCmp cmp] {l : List α} :
  Std.ExtDTreeMap.Const.unitOfList l cmp = Std.ExtDTreeMap.Const.insertManyIfNewUnit ∅ l

theorem Std.ExtDTreeMap.get_get?.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] {a : α}
  {h : (t.get? a).isSome = true} : (t.get? a).get h = t.get a ⋯

theorem Std.ExtDTreeMap.Const.get?_diff_of_not_mem_left.{u, v} {α : Type u} {cmp : α → α → Ordering}
  {β : Type v} {t₁ t₂ : Std.ExtDTreeMap α (fun x => β) cmp} [Std.TransCmp cmp] {k : α}
  (h : k ∉ t₁) : Std.ExtDTreeMap.Const.get? (t₁ \ t₂) k = none

theorem Std.ExtDTreeMap.Const.get!_union_of_not_mem_right.{u, v} {α : Type u} {cmp : α → α → Ordering}
  {β : Type v} {t₁ t₂ : Std.ExtDTreeMap α (fun x => β) cmp} [Std.TransCmp cmp] [Inhabited β] {k : α}
  (not_mem : k ∉ t₂) : Std.ExtDTreeMap.Const.get! (t₁.union t₂) k = Std.ExtDTreeMap.Const.get! t₁ k

theorem Std.ExtDTreeMap.minKey?_eq_some_iff_mem_and_forall.{u, v} {α : Type u} {β : α → Type v}
  {cmp : α → α → Ordering} {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp]
  {km : α} : t.minKey? = some km ↔ km ∈ t ∧ ∀ k ∈ t, (cmp km k).isLE = true

theorem Std.ExtDTreeMap.getKey!_congr.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] [Inhabited α] {k k' : α}
  (h' : cmp k k' = Ordering.eq) : t.getKey! k = t.getKey! k'

theorem Std.ExtDTreeMap.getKey!_maxKey!.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] [Inhabited α] (he : t ≠ ∅) :
