theorem Std.ExtDTreeMap.eq_empty_iff_forall_contains.{u, v} {α : Type u} {β : α → Type v}
  {cmp : α → α → Ordering} {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] :
  t = ∅ ↔ ∀ (a : α), t.contains a = false

