theorem Std.ExtDTreeMap.Const.get?_eq_none_of_contains_eq_false.{u, v} {α : Type u} {cmp : α → α → Ordering}
  {β : Type v} {t : Std.ExtDTreeMap α (fun x => β) cmp} [Std.TransCmp cmp] {a : α} :
  t.contains a = false → Std.ExtDTreeMap.Const.get? t a = none

theorem Std.ExtDTreeMap.Const.getD_insertMany_list_of_mem.{u, v} {α : Type u} {cmp : α → α → Ordering}
  {β : Type v} {t : Std.ExtDTreeMap α (fun x => β) cmp} [Std.TransCmp cmp] {l : List (α × β)}
  {k k' : α} (k_eq : cmp k k' = Ordering.eq) {v fallback : β}
