theorem Std.ExtDTreeMap.Const.get?_inter_of_not_mem_right.{u, v} {α : Type u} {cmp : α → α → Ordering}
  {β : Type v} {t₁ t₂ : Std.ExtDTreeMap α (fun x => β) cmp} [Std.TransCmp cmp] {k : α}
  (h : k ∉ t₂) : Std.ExtDTreeMap.Const.get? (t₁ ∩ t₂) k = none

theorem Std.ExtDTreeMap.mem_erase.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] {k a : α} :
  a ∈ t.erase k ↔ cmp k a ≠ Ordering.eq ∧ a ∈ t

theorem Std.ExtDTreeMap.contains_diff.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t₁ t₂ : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] {k : α} :
  (t₁ \ t₂).contains k = (t₁.contains k && !t₂.contains k)

theorem Std.ExtDTreeMap.getD_eq_fallback_of_contains_eq_false.{u, v} {α : Type u} {β : α → Type v}
