  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] {a : α} (h' : a ∈ t) :
  t.get? a = some (t.get a h')

theorem Std.ExtDTreeMap.get!_diff_of_mem_right.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t₁ t₂ : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] {k : α}
