  List.find? (fun x => cmp x.fst k == Ordering.eq) t.toList = none ↔ k ∉ t

theorem Std.ExtDTreeMap.get!_modify.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] [Std.LawfulEqCmp cmp] {k k' : α}
  [hi : Inhabited (β k')] {f : β k → β k} :
  (t.modify k f).get! k' =
    if heq : cmp k k' = Ordering.eq then (Option.map (cast ⋯) (Option.map f (t.get? k))).get!
    else t.get! k'

theorem Std.ExtDTreeMap.containsThenInsert_snd.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
