  (a a✝ : α) (e_a : a = a✝) : Std.ExtDTreeMap.Const.get! t a = Std.ExtDTreeMap.Const.get! t✝ a✝

theorem Std.ExtDTreeMap.inter.congr_simp.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  [Std.TransCmp cmp] (m₁ m₁✝ : Std.ExtDTreeMap α β cmp) (e_m₁ : m₁ = m₁✝)
  (m₂ m₂✝ : Std.ExtDTreeMap α β cmp) (e_m₂ : m₂ = m₂✝) : m₁.inter m₂ = m₁✝.inter m₂✝

theorem Std.ExtDTreeMap.maxKey_insertIfNew.{u, v} {α : Type u} {β : α → Type v} {cmp : α → α → Ordering}
  {t : Std.ExtDTreeMap α β cmp} [Std.TransCmp cmp] {k : α} {v : β k} :
  (t.insertIfNew k v).maxKey ⋯ = t.maxKey?.elim k fun k' => if cmp k' k = Ordering.lt then k else k'

theorem Std.ExtDTreeMap.Const.get!_filter.{u, v} {α : Type u} {cmp : α → α → Ordering} {β : Type v}
  {t : Std.ExtDTreeMap α (fun x => β) cmp} [Std.TransCmp cmp] [Inhabited β] {f : α → β → Bool}
